        this.subtotal = subtotal;
    }

    public double price() {
        return applyTax(subtotal, TAX_RATE);
    }

    static double applyTax(double amount, double rate) {
        // The tax is applied on the whole subtotal.
        return amount * (1 + rate);
    }
}

